// Generated by AI (UnitTest MCP)
//
// The board asks the ledger for everything, then asks again per finished item.
//
// Measured against the live ledger on 2026-07-31: one refresh rendered 75 rows
// of which 5 were actionable, and cost 70 MCP calls -- 69 of them fetching
// promotion detail for `materialized` designs, work that is done and that
// nobody is being asked to decide. The refresh is wired to a file watcher over
// docs/adr, so every ADR touch paid it again.
//
// `design_query` already names the right question. Its own description defines
// view=board as "actionable items: proposed ADRs awaiting a human decision plus
// accepted designs awaiting or retrying promotion" -- which is the board this
// view is named after. These tests pin the view and the fan-out, because the
// fan-out is invisible from the UI and would come back unnoticed.
import { beforeEach, describe, expect, it, vi } from "vitest";

const vscodeMock = vi.hoisted(() => ({
  showErrorMessage: vi.fn(),
  showInformationMessage: vi.fn(),
  showWarningMessage: vi.fn(),
}));

vi.mock("vscode", () => ({ window: vscodeMock, workspace: { workspaceFolders: [] } }));

import { DesignBoardController } from "./designBoardController";

const design = (id: string, promotionStatus: string) => ({
  id,
  title: id,
  status: "accepted",
  promotion_status: promotionStatus,
  created_at: 1,
});

/** A ledger shaped like the live one: a few actionable, most long finished. */
const ledger = [
  design("design:0001", "pending"),
  design("design:0002", "pending"),
  ...Array.from({ length: 69 }, (_, index) => design(`design:done-${index}`, "materialized")),
];

function controller() {
  const calls: { name: string; args: Record<string, unknown> }[] = [];
  const callTool = vi.fn(async (name: string, args: Record<string, unknown>) => {
    calls.push({ name, args });
    if (name !== "design_query") return null;
    if (args.view === "ledger") return ledger;
    // What the server actually returns for the actionable view.
    if (args.view === "board") return ledger.filter((d) => d.promotion_status === "pending");
    if (args.view === "promotion") return { design_id: args.id, objectives: [] };
    return null;
  });
  const provider = { update: vi.fn() };
  const instance = new DesignBoardController(
    { isReady: () => true, callTool } as never,
    provider as never,
    "session:v1:test",
    vi.fn(),
    vi.fn(),
    vi.fn(async () => undefined)
  );
  return { instance, calls, provider, callTool };
}

describe("DesignBoardController refresh", () => {
  beforeEach(() => vi.clearAllMocks());

  it("asks for the actionable designs, not the whole durable record", async () => {
    const { instance, calls } = controller();

    await instance.refresh();

    const views = calls.filter((c) => c.name === "design_query").map((c) => c.args.view);
    expect(views).toContain("board");
    expect(views).not.toContain("ledger");
  });

  /// The fan-out is the expensive half and the invisible one: one extra call
  /// per finished design, on a refresh a file watcher triggers.
  it("does not fetch promotion detail for work nobody is being asked to decide", async () => {
    const { instance, calls } = controller();

    await instance.refresh();

    const promotionCalls = calls.filter(
      (c) => c.name === "design_query" && c.args.view === "promotion"
    );
    expect(promotionCalls.length).toBe(0);
    expect(calls.length).toBeLessThanOrEqual(2);
  });

  it("still hands the rows it fetched to the view", async () => {
    const { instance, provider } = controller();

    await instance.refresh();

    expect(provider.update).toHaveBeenCalledTimes(1);
    const [designs] = provider.update.mock.calls[0];
    expect(designs).toHaveLength(2);
  });
});
